    afterGrant: [
      "Your new travel facility starts on the grant date and replaces any facility left on your previous visa; the unused balance is lost and not refunded.",
      "You can travel in and out of Australia as often as you like until the facility expires. If it expires while you are outside Australia your permanent visa ceases and you need another RRV to return as a permanent resident.",
      "If you are in Australia when the facility expires you remain a permanent resident; you only need an RRV if you want to travel.",
      "New Zealand citizens should tell the border officer they hold a permanent visa and do not want a Special Category visa; an SCV grant would cease the permanent visa.",
      "Returning on a temporary visa such as an ETA or visitor visa instead of an RRV can affect Medicare, work rights and your ability to meet the residence requirements for citizenship or a later RRV.",
      "There is no limit on how many RRVs you can hold over time, but each one is assessed afresh against the residence or ties tests.",
    ],
    pathways: [
      { title: "Australian citizenship", description: "Once you have 4 years of lawful residence including 12 months as a permanent resident, with limited absences, citizenship ends the need for travel facilities.", href: "/visas/other-visas/australian-citizenship-by-conferral" },
      { title: "Former Resident visa", description: "People who grew up in Australia as permanent residents but no longer hold a permanent visa may qualify for subclass 151 instead.", href: "/visas/other-visas/former-resident-visa-151" },
      { title: "Special Category visa for New Zealand citizens", description: "New Zealand citizens who do not hold a permanent visa can enter on an SCV, but an SCV is temporary and ceases a permanent visa if granted by mistake.", href: "/visas/other-visas/special-category-visa-444" },
      { title: "Book a consultation", description: "Discuss how days are counted, what counts as substantial ties, and whether to wait before lodging.", href: "/bookings" },
    ],
    risks: [
      "Lodging before you have 730 days in Australia in the last 5 years: you receive a 12-month facility and the Department will not refund the charge or grant a 5-year facility later without a new application.",
      "Returning to Australia on an ETA, eVisitor or visitor visa after your facility expired, which can affect entitlements and the residence count for citizenship or a later RRV.",
      "A New Zealand citizen permanent resident being granted an SCV at the border, which ceases the permanent visa.",
      "Claiming substantial ties without documents: ties must be both substantial and of benefit to Australia, and family relationships alone may not be enough.",
      "Absences of 5 continuous years or more (or, for option 3, more than 5 years in total since you left as a permanent resident or citizen) without compelling reasons.",
      "Applying while a business skills visa is under cancellation consideration, which makes the RRV application invalid.",
    ],
    faqs: [
      { question: "How long is the travel facility on an RRV?", answer: "Five years if you were in Australia for at least 2 of the last 5 years (730 days) as a permanent resident or citizen. Twelve months if you rely on substantial ties or on a family member's RRV. Three months on a subclass 157 where you have compelling and compassionate reasons for your absence. The facility cannot be extended." },
      { question: "How much does a Resident Return visa cost?", answer: "A$1,475 per applicant from 1 July 2026 when you apply online, plus A$80 if the Department authorises a paper application. Each family member pays their own charge. A lower charge applies to eligible Pacific Island and Timor-Leste passport holders." },
      { question: "Can I apply from outside Australia?", answer: "Yes. You can be in or outside Australia when you apply and when the visa is granted, as long as you are not in immigration clearance. If you are outside Australia and your facility has expired, you need the RRV before you board a flight to Australia." },
      { question: "What counts as substantial ties?", answer: "Home Affairs recognises business, cultural, employment and personal ties, and they must be both substantial and of benefit to Australia. Examples include an ongoing Australian job or business, Australian citizen children living in Australia, long formative-year residence, and property and community involvement. Provide documents, not just a statement." },
      { question: "I am in Australia and my travel facility has expired. Am I still a permanent resident?", answer: "Yes. Your permanent visa stays valid while you remain in Australia and it is not cancelled. You only need an RRV if you want to travel overseas and return as a permanent resident." },
      { question: "Will I get a refund if I lodge too early?", answer: "Generally no. Home Affairs does not refund the charge because your application was refused, because you lost the remaining facility on your old visa, because you did not use the new facility, or because you lodged before meeting the residence test and received only a 12-month facility." },
      { question: "I am a New Zealand citizen. Do I need an RRV?", answer: "Only if you hold or held a permanent visa, or are treated as a former permanent resident because you arrived before 1 September 1994 and usually resided in Australia. New Zealand citizens who arrived on or after that date and do not hold a permanent visa use the Special Category visa, and since 1 July 2023 can apply directly for citizenship." },
    ],
